# -*- coding: utf-8 -*-
import json, pathlib, hashlib
root=pathlib.Path('analysis/native_decode/decoded')
out=pathlib.Path('analysis/activity-push-2026-10-21/engine')
rows=[]
def add(id,title,rule,refs,boundary='仅证明此客户端实现，不证明线上启用或送达'):
    evidence=[]
    for path,needle in refs:
        text=(root/path).read_text(); lines=text.splitlines()
        matches=[i+1 for i,l in enumerate(lines) if needle in l]
        assert matches,(path,needle)
        evidence.append(dict(path=str(root/path),line=matches[0],anchor=needle,sha256=hashlib.sha256((root/path).read_bytes()).hexdigest()))
    rows.append(dict(id=id,title=title,rule=rule,evidence=evidence,boundary=boundary))
